import { test } from "@e2e/fixtures";
import * as ui from "@e2e/ui-actions";

test.describe("Voice functionality", () => {
  test("Voice and send button toggle based on input text", async ({ inspectorPage }) => {
    await test.step("Assert voice button visible and send button hidden when input is empty", async () => {
      await ui.voiceControls.assertions(inspectorPage).voiceStartButtonIsVisible();
      await ui.voiceControls.assertions(inspectorPage).sendMessageButtonIsHidden();
    });

    await test.step("Type text in message input", async () => {
      await ui.voiceControls.actions(inspectorPage).typeMessage("Hello");
    });

    await test.step("Assert send button visible and voice button hidden", async () => {
      await ui.voiceControls.assertions(inspectorPage).sendMessageButtonIsVisible();
      await ui.voiceControls.assertions(inspectorPage).voiceStartButtonIsHidden();
    });

    await test.step("Clear message input", async () => {
      await ui.voiceControls.actions(inspectorPage).clearMessage();
    });

    await test.step("Assert voice button visible and send button hidden", async () => {
      await ui.voiceControls.assertions(inspectorPage).voiceStartButtonIsVisible();
      await ui.voiceControls.assertions(inspectorPage).sendMessageButtonIsHidden();
    });
  });

  test("Voice call workflow: start, verify active state, stop", async ({ inspectorPage }) => {
    await test.step("Click start voice call", async () => {
      await ui.voiceControls.actions(inspectorPage).startVoiceCall();
    });

    await test.step("Assert connecting or active state", async () => {
      await ui.voiceControls.assertions(inspectorPage).connectingOrActiveStateIsVisible();
    });

    await test.step("Assert active voice call state", async () => {
      await ui.voiceControls.assertions(inspectorPage).activeStateIsVisible();
      await ui.voiceControls.assertions(inspectorPage).voiceStopButtonIsVisible();
    });

    await test.step("Assert voice call timer has incremented", async () => {
      await ui.voiceControls.assertions(inspectorPage).timerHasIncremented();
    });

    await test.step("Click stop voice call", async () => {
      await ui.voiceControls.actions(inspectorPage).stopVoiceCall();
    });

    await test.step("Assert inactive voice state", async () => {
      await ui.voiceControls.assertions(inspectorPage).inactiveStateIsVisible();
      await ui.voiceControls.assertions(inspectorPage).voiceStartButtonIsVisible();
    });
  });
});
